 if f.endswith('ensemble.json'): continue
 try:
  d=json.load(open(f)); print(os.path.basename(f), {k:d.get(k) for k in ('factor_id','name','category','ic','icir','turnover','coverage','direction')})
 except Exception as e: print(f,e)
PY
